'use strict';
// L10-J: the PSD adapter against the baseline `psd-import-bridge.js` oracle (tests/fixtures/native-import-adapters/psd-plan.json, generated by
// tools/gen_psd.mjs from fbe4b8a3 by running the verbatim importChildren / importFile body). ag-psd stays the parser behind the readPsd
// port; every layer is a raster, so the owner refuses the batch with the named provider and nothing is published or resized.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const psd = require('../src/js/adapters/native-import-psd.js');
const coreModule = require('../src/js/adapters/native-import-core.js');
const { makeSession, makePorts } = require('./helpers/native-import-session.cjs');

const FIX = JSON.parse(fs.readFileSync(path.join(__dirname, 'fixtures', 'native-import-adapters', 'psd-plan.json'), 'utf8'));
const ADAPTER = path.join(__dirname, '..', 'src', 'js', 'adapters', 'native-import-psd.js');
const un = (v) => (v && typeof v === 'object' && v.undefined === true ? undefined : v);
const J = (v) => JSON.stringify(v);

// The ag-psd object the baseline received for a case row.
function psdOf(c) {
  const children = un(c.children);
  return {
    width: un(c.psd.width), height: un(c.psd.height),
    children: children === undefined ? undefined : children.map((l) => ({ name: un(l.name), hidden: l.hidden || undefined, canvas: l.canvas ? { width: l.canvas[0], height: l.canvas[1] } : undefined, left: un(l.left), top: un(l.top), opacity: un(l.opacity) })),
  };
}
function load(edits) {
  let source = fs.readFileSync(ADAPTER, 'utf8');
  for (const [from, to] of edits || []) {
    assert.equal(source.split(from).length, 2, `mutation anchor must occur exactly once: ${from}`);
    source = source.replace(from, to);
  }
  const m = { exports: {} };
  new Function('module', 'exports', source)(m, m.exports);
  return m.exports;
}
// What the oracle row records, rebuilt from the plan.
function observed(mod, c) {
  const p = mod.plan(psdOf(c), { w: c.canvas[0], h: c.canvas[1] });
  return { resize: p.resize ? [p.resize] : [], count: p.error ? undefined : p.count, error: p.error || undefined,
    rasters: p.rows.map((r) => ({ src: r.childIndex, name: r.name, x: r.x, y: r.y, w: r.w, h: r.h, opacity: r.opacity })) };
}
const wanted = (c) => ({ resize: c.expect.resize, count: c.expect.outcome.count, error: c.expect.outcome.error, rasters: c.expect.rasters });

test('fixture pins the baseline commit and its row counts', () => {
  assert.equal(FIX.meta.baseline, 'fbe4b8a33e6d5a229f014154df2ba21988a9fabc');
  assert.deepEqual(FIX.meta.counts, { cases: 45, layers: 129 });
  assert.equal(FIX.cases.filter((c) => c.expect.outcome.error !== undefined).length, 10);
  assert.equal(FIX.cases.filter((c) => c.expect.resize.length).length, 24);
  assert.ok(FIX.cases.every((c) => c.expect.undo === 1), 'the baseline pushed exactly one undo step per import');
});

test('every baseline PSD plans the same layers, names, placement, opacity, canvas resize and no-pixels failure', () => {
  for (const c of FIX.cases) assert.deepEqual(JSON.parse(J(observed(psd, c))), JSON.parse(J(wanted(c))), c.id);
});

test('rows plus skipped children cover every child: a group or a hidden layer is reported, never dropped', () => {
  for (const c of FIX.cases) {
    const p = psd.plan(psdOf(c), { w: c.canvas[0], h: c.canvas[1] });
    assert.equal(p.rows.length + p.skipped.length, p.childCount, c.id);
    assert.deepEqual(p.rows.map((r) => r.childIndex).concat(p.skipped.map((s) => s.childIndex)).sort((a, b) => a - b), Array.from({ length: p.childCount }, (_, i) => i), c.id);
  }
  const p = psd.plan({ children: [{ canvas: undefined, hidden: true }, { canvas: { width: 1, height: 1 }, hidden: true }, { canvas: undefined }] }, { w: 1, h: 1 });
  assert.deepEqual(p.skipped.map((s) => s.reason), ['no-canvas', 'hidden', 'no-canvas'], 'a hidden group is reported as a group');
});

test('the two toast expressions equal the baseline for every locale', () => {
  for (const [i, c] of FIX.cases.entries()) {
    const t = (k) => FIX.meta.templates[c.locale][k];
    const toast = c.expect.outcome.error === undefined ? psd.successToast(c.expect.outcome.count, t) : psd.failureToast({ message: c.expect.outcome.error }, t);
    assert.equal(toast, c.expect.toast, `${c.id} (${i})`);
  }
  assert.equal(psd.failureToast(undefined, (k) => k), 'toastPsdImportFailedSuffixerreur inconnue');
  assert.equal(psd.failureToast({ message: '' }, (k) => k), 'toastPsdImportFailedSuffixerreur inconnue');
});

function importer(c, sessionOptions) {
  const h = makeSession(Object.assign({ canvasW: c.canvas[0], canvasH: c.canvas[1] }, sessionOptions));
  const toasts = [], resized = [];
  const adapter = psd.create({
    core: coreModule.create(makePorts(h, { maxRequestBytes: 1 << 20 }).ports), t: (k) => FIX.meta.templates[c.locale][k], notify: (m) => toasts.push(m),
    readPsd: async () => psdOf(c), resizeCanvas: async (w, hh) => { resized.push([w, hh]); return 'applied'; },
  });
  return { h, toasts, resized, run: () => adapter.importFile({ name: 'x.psd' }) };
}

test('a PSD with pixels needs the raster provider: the owner refuses the whole batch, the canvas stays and nothing is toasted as success', async () => {
  for (const c of FIX.cases.filter((x) => x.expect.outcome.error === undefined)) {
    const run = importer(c);
    const result = await run.run();
    assert.equal(result.status, 'unavailable', c.id);
    assert.equal(result.reason, 'native_refused');
    assert.deepEqual(result.unavailable, ['raster-asset']);
    assert.equal(result.eligible, c.expect.outcome.count);
    assert.equal(run.h.state.contentRevision, 7, `${c.id}: nothing published`);
    assert.deepEqual(run.resized, [], `${c.id}: the baseline resized here; the native import only resizes after a committed batch`);
    assert.deepEqual(run.toasts, []);
    const sent = run.h.calls[0];
    assert.deepEqual(sent.layers.map((l) => l.name), c.expect.rasters.map((r) => r.name), c.id);
    assert.deepEqual(sent.layers.map((l) => l.sourceId), c.expect.rasters.map((r) => `psd:${r.src}`));
    assert.deepEqual(sent.unavailable.map((u) => [u.sourceId, u.need]), c.expect.rasters.map((r) => [`psd:${r.src}`, 'raster-asset']));
    assert.deepEqual(sent.records, []);
    assert.equal(sent.skipped.length + sent.layers.length, (un(c.children) || []).length, `${c.id}: every child is a layer or a typed skip`);
  }
});

test('a PSD with no pixels fails with the baseline message and toast, sends nothing and leaves the canvas', async () => {
  const c = FIX.cases.find((x) => x.id === 'only_groups');
  const run = importer(c);
  const result = await run.run();
  assert.deepEqual([result.status, result.message], ['failed', psd.NO_PIXELS]);
  assert.deepEqual(run.toasts, [c.expect.toast]);
  assert.equal(run.h.calls.length, 0);
  assert.deepEqual(run.resized, [], 'the baseline resized the canvas even though nothing was importable');
  assert.equal(c.expect.resize.length, 1);
});

test('a parse error is the baseline failure toast; an absent native session is typed unavailable before the file is read', async () => {
  const c = FIX.cases[0];
  const toasts = [];
  const h = makeSession();
  const adapter = psd.create({ core: coreModule.create(makePorts(h).ports), t: (k) => k, notify: (m) => toasts.push(m), readPsd: async () => { throw new Error('bad psd'); } });
  const failed = await adapter.importFile({});
  assert.deepEqual([failed.status, failed.message, toasts], ['failed', 'bad psd', ['toastPsdImportFailedSuffixbad psd']]);
  let read = 0;
  const gone = makeSession({ declared: false });
  const out = await psd.create({ core: coreModule.create(makePorts(gone).ports), t: (k) => k, readPsd: async () => { read += 1; return psdOf(c); } }).importFile({});
  assert.deepEqual(out, { status: 'unavailable', reason: 'native_declaration_absent' });
  assert.equal(read, 0);
});

test('an owner that accepted rows needing a missing provider is reported unconfirmed, never as an import', async () => {
  const c = FIX.cases.find((x) => x.id === 'single_all_fields');
  const h = makeSession();
  const toasts = [];
  const ports = makePorts(h, { maxRequestBytes: 1 << 20 }).ports;
  const core = coreModule.create(ports);
  const lenient = { begin: core.begin, submit: async (ctx, batch) => core.submit(ctx, Object.assign({}, batch, { unavailable: [] })) };
  const out = await psd.create({ core: lenient, t: (k) => k, notify: (m) => toasts.push(m), readPsd: async () => psdOf(c), resizeCanvas: async () => { throw new Error('must not resize'); } }).importFile({});
  assert.equal(out.status, 'unconfirmed');
  assert.equal(out.reason, 'owner_accepted_unavailable_rows');
  assert.deepEqual(toasts, []);
});

test('the reader runs ag-psd lazily over the file bytes', async () => {
  const seen = [];
  const read = psd.readerFor(async () => ({ readPsd: (buffer) => { seen.push(buffer); return { width: 1, height: 2 }; } }));
  assert.deepEqual(await read({ arrayBuffer: async () => 'bytes' }), { width: 1, height: 2 });
  assert.deepEqual(seen, ['bytes']);
});

// ---- negative controls ----
function mismatches(mod) {
  let bad = 0;
  for (const c of FIX.cases) { try { if (J(observed(mod, c)) !== J(wanted(c))) bad += 1; } catch (_) { bad += 1; } }
  return bad;
}
test('controls: the unmutated planner has no mismatch and every source mutation is rejected', () => {
  assert.equal(mismatches(psd), 0);
  const mutants = [
    ['hidden layers imported', [['if (!layer.canvas || layer.hidden) {', 'if (!layer.canvas) {']]],
    ['canvas-less layers imported', [['if (!layer.canvas || layer.hidden) {', 'if (layer.hidden) {']]],
    ['name counter counts skipped children', [["(rows.length + 1)", "(childIndex + 1)"]]],
    ['placement is the top-left corner', [['x: left + w / 2, y: top + h / 2,', 'x: left, y: top,']]],
    ['missing left/top not zero', [['const left = layer.left || 0, top = layer.top || 0;', 'const left = layer.left, top = layer.top;']]],
    ['opacity default dropped', [['opacity: layer.opacity !== undefined ? layer.opacity : 1,', 'opacity: layer.opacity,']]],
    ['opacity falsy defaults to one', [['opacity: layer.opacity !== undefined ? layer.opacity : 1,', 'opacity: layer.opacity || 1,']]],
    ['resize on any difference only when both differ', [['psd.width !== canvas.w || psd.height !== canvas.h', 'psd.width !== canvas.w && psd.height !== canvas.h']]],
    ['resize without a size guard', [['(psd.width && psd.height && (', '(psd.width !== undefined && psd.height !== undefined && (']]],
    ['no-pixels not an error', [['error: rows.length ? null : NO_PIXELS', 'error: null']]],
  ];
  for (const [name, edits] of mutants) assert.ok(mismatches(load(edits)) > 0, `mutation not caught: ${name}`);
});
